before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <string>
#include <vector>
struct Notebook {
    std::string name;
    std::vector<int> pages;
};
int main() {
    Notebook a{"Ideas", {1, 2}};
    Notebook b = a;
    b.pages.push_back(3);
    std::cout << a.pages.size() << ' ' << b.pages.size() << '\n';
}

```

